#include <stdio.h>
int main(void){int a[10][10],b[10][10],c[10][10]={0},r1,c1,r2,c2;printf("Rows/cols of A: ");if(scanf("%d %d",&r1,&c1)!=2||r1<1||r1>10||c1<1||c1>10)return 1;printf("Rows/cols of B: ");if(scanf("%d %d",&r2,&c2)!=2||r2<1||r2>10||c2<1||c2>10||c1!=r2){puts("Incompatible dimensions.");return 1;}for(int i=0;i<r1;i++)for(int j=0;j<c1;j++)if(scanf("%d",&a[i][j])!=1)return 1;for(int i=0;i<r2;i++)for(int j=0;j<c2;j++)if(scanf("%d",&b[i][j])!=1)return 1;for(int i=0;i<r1;i++)for(int j=0;j<c2;j++)for(int k=0;k<c1;k++)c[i][j]+=a[i][k]*b[k][j];puts("Product:");for(int i=0;i<r1;i++){for(int j=0;j<c2;j++)printf("%d ",c[i][j]);puts("");}return 0;}
